from pathlib import Path
import subprocess,shutil,json,os
p=Path(__file__).resolve().parent;root=Path.cwd()
sources=[(Path('shaders/physics/'+name),name) for name in ['solve.wgsl','integrate.wgsl']]
for src,name in sources:assert src.read_bytes()==(p/('original-'+name)).read_bytes()
try:
 for src,name in sources:src.write_bytes((p/('diagnostic-'+name)).read_bytes())
 manifest='[package]\nname="rain-phase-bridge"\nversion="0.1.0"\nedition="2021"\n[workspace]\n[lib]\npath="bridge.rs"\ncrate-type=["staticlib"]\n[dependencies]\npollster="0.4"\ngpu-physics={path='+json.dumps(str(root))+',features=["replay-diagnostics"]}\n'
 (p/'Cargo.toml').write_text(manifest);shutil.copy2('Cargo.lock',p/'Cargo.lock')
 with (p/'build.log').open('w') as log:r=subprocess.run(['cargo','build','--offline','--release','--manifest-path',str(p/'Cargo.toml'),'--target-dir',str(root/'target')],env=os.environ|{'CARGO_BUILD_JOBS':'1'},stdout=log,stderr=subprocess.STDOUT)
 (p/'build-exit.json').write_text(json.dumps({'exit':r.returncode}))
 if r.returncode:raise SystemExit(r.returncode)
 shutil.copy2('target/release/librain_phase_bridge.a',p/'libphase_bridge.a')
finally:
 for src,name in sources:src.write_bytes((p/('original-'+name)).read_bytes())
 (p/'restoration.json').write_text(json.dumps({str(src):src.read_bytes()==(p/('original-'+name)).read_bytes() for src,name in sources}))

