use gpu_physics::api::{WorldId,b3_world_sync_phase_words};
use std::{ffi::CStr,os::raw::c_char,io::Write};
#[no_mangle]
pub unsafe extern "C" fn diagnostic_write_phases(id:WorldId,path:*const c_char,frame:u32)->bool {
    if path.is_null(){return false;}
    let Ok(path)=CStr::from_ptr(path).to_str() else{return false;};
    let words=pollster::block_on(b3_world_sync_phase_words(id));
    if words.len()<192 || (words.len()-192)%192!=0{return false;}
    let Ok(mut file)=std::fs::OpenOptions::new().create(true).append(true).open(path) else{return false;};
    for word in [frame,words.len() as u32].into_iter().chain(words){
        if file.write_all(&word.to_le_bytes()).is_err(){return false;}
    }
    true
}

